import re

_PATTERN = re.compile(r"^\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*$")

_SECONDS = {
    "d": 86400,
    "h": 3600,
    "m": 60,
    "s": 1,
}

def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("duration must be a string")
    match = _PATTERN.match(s)
    if match is None:
        raise ValueError("invalid duration: %r" % (s,))
    if not any(part is not None for part in match.groups()):
        raise ValueError("invalid duration: %r" % (s,))
    total = 0
    for amount, unit in zip(match.groups(), ("d", "h", "m", "s")):
        if amount is not None:
            total += int(amount) * _SECONDS[unit]
    return total
